alter table public.cele add column if not exists sniadanie_procent double precision not null default 25;
alter table public.cele add column if not exists drugie_sniadanie_procent double precision not null default 10;
alter table public.cele add column if not exists obiad_procent double precision not null default 35;
alter table public.cele add column if not exists podwieczorek_procent double precision not null default 10;
alter table public.cele add column if not exists kolacja_procent double precision not null default 20;
create table if not exists public.plan_diety(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),data date not null unique);
create table if not exists public.plan_uczestnicy(id bigint generated by default as identity primary key,plan_id bigint not null references public.plan_diety(id) on delete cascade,osoba text not null,unique(plan_id,osoba));
create table if not exists public.pozycje_planu(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),plan_id bigint not null references public.plan_diety(id) on delete cascade,rodzaj_posilku text not null,produkt_id bigint references public.produkty(id) on delete restrict,posilek_id bigint references public.posilki(id) on delete restrict);
create table if not exists public.porcje_planu(id bigint generated by default as identity primary key,pozycja_planu_id bigint not null references public.pozycje_planu(id) on delete cascade,osoba text not null,gramy double precision not null,kcal double precision not null default 0,bialko double precision not null default 0,tluszcz double precision not null default 0,weglowodany double precision not null default 0,unique(pozycja_planu_id,osoba));
alter table public.plan_diety enable row level security;alter table public.plan_uczestnicy enable row level security;alter table public.pozycje_planu enable row level security;alter table public.porcje_planu enable row level security;
grant select,insert,update,delete on public.plan_diety,public.plan_uczestnicy,public.pozycje_planu,public.porcje_planu to authenticated;
revoke all on public.plan_diety,public.plan_uczestnicy,public.pozycje_planu,public.porcje_planu from anon;
drop policy if exists "Zalogowani zarzadzaja planami" on public.plan_diety;create policy "Zalogowani zarzadzaja planami" on public.plan_diety for all to authenticated using(true) with check(true);
drop policy if exists "Zalogowani zarzadzaja uczestnikami planu" on public.plan_uczestnicy;create policy "Zalogowani zarzadzaja uczestnikami planu" on public.plan_uczestnicy for all to authenticated using(true) with check(true);
drop policy if exists "Zalogowani zarzadzaja pozycjami planu" on public.pozycje_planu;create policy "Zalogowani zarzadzaja pozycjami planu" on public.pozycje_planu for all to authenticated using(true) with check(true);
drop policy if exists "Zalogowani zarzadzaja porcjami planu" on public.porcje_planu;create policy "Zalogowani zarzadzaja porcjami planu" on public.porcje_planu for all to authenticated using(true) with check(true);
